recipes.code:
{
  "inputs": [
    {
      "id": "pingwa-key",
      "type": "promptString",
      "description": "pingwa API key (send 'join' on WhatsApp to the service number — see https://pingwa.dev)",
      "password": true
    }
  ],
  "servers": {
    "pingwa": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "pingwa@0.4.1"
      ],
      "env": {
        "PINGWA_KEY": "${input:pingwa-key}"
      }
    }
  }
}
